const crypto=require('crypto');
const e=$input.first()?.json||{};
const wf=e.workflow||e.data?.workflow||{};
const exec=e.execution||e.data?.execution||{};
const nodeErr=e.trigger?.error||e.error||exec.error||{};
const message=nodeErr.message||e.message||'Sin mensaje de error';
const nodeName=nodeErr.node?.name||e.node?.name||exec.lastNodeExecuted||'desconocido';
const workflowName=wf.name||e.workflowName||'desconocido';
const workflowId=wf.id||e.workflowId||'?';
const executionId=exec.id||e.executionId||'?';
const executionUrl=exec.url||e.executionUrl||'';
const now=Date.now();
const throttleMs=15*60*1000;
const globalLimit=3;
const signature=crypto.createHash('sha256').update(`${workflowId}|${nodeName}|${message}`).digest('hex');
const state=$getWorkflowStaticData('global');
state.errorThrottle=state.errorThrottle||{};
state.errorGlobalWindow=Array.isArray(state.errorGlobalWindow)?state.errorGlobalWindow.filter(timestamp=>now-Number(timestamp)<throttleMs):[];
for(const [key,timestamp] of Object.entries(state.errorThrottle)){if(now-Number(timestamp)>24*60*60*1000)delete state.errorThrottle[key];}
if(state.errorThrottle[signature]&&now-Number(state.errorThrottle[signature])<throttleMs)return [];
if(state.errorGlobalWindow.length>=globalLimit)return [];
state.errorThrottle[signature]=now;
state.errorGlobalWindow.push(now);
const subject=`🔴 BYG: falló el workflow "${workflowName}"`;
const body=`<b>Workflow:</b> ${workflowName} (${workflowId})<br>`+`<b>Nodo:</b> ${nodeName}<br>`+`<b>Execution ID:</b> ${executionId}<br>`+`<b>Mensaje:</b> ${message}<br>`+`<b>URL:</b> ${executionUrl}`;
return [{json:{subject,body,throttle_signature:signature}}];
